pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max);
        vm.startPrank(address(this));
        c.OpenToThePublic();
        vm.roll(1);
        c.AdjustBetAmounts(amount);
        vm.roll(2);
        vm.recordLogs();
        c.AdjustBetAmounts(amount + 1);
        vm.stopPrank();
        Vm.Log[] memory logs = vm.getRecordedLogs();
        assertTrue(logs.length > 0);
        uint256 emittedDifficulty;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == keccak256("DifficultyChanged(uint256)")) {
                emittedDifficulty = abi.decode(logs[i].data, (uint256));
            }
        }
        assertTrue(emittedDifficulty == c.currentDifficulty());
    }
}

