pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Include amount = 0 in admissible domain; the bug subtracts 1 causing underflow,
        // which still violates the property for many values.
        // Ensure owner can call both functions.
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);

        vm.prank(address(this));
        c.AdjustDifficulty(amount);

        // The property: after both calls, difficulty must equal the last amount set (which is amount).
        // The mutant sets difficulty = amount - 1, violating equality for any amount > 0.
        assertEq(c.currentDifficulty(), amount);
    }
}

